<?php
require __DIR__.'/../includes/functions.php'; require_login('admin');$error=null;$edit=null;$id=(int)($_GET['id']??0);
if($id){$q=db()->prepare('SELECT id,name,mobile,role,is_active,last_login_at,created_at FROM users WHERE id=?');$q->execute([$id]);$edit=$q->fetch();if(!$edit)redirect('/admin/users.php');}
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=$_POST['action']??'';$uid=(int)($_POST['id']??0);if($uid===user()['id']&&$action==='toggle'){$error='نمی‌توانید حساب مدیرِ خودتان را غیرفعال کنید.';}elseif($action==='save'){$name=trim($_POST['name']??'');$mobile=trim($_POST['mobile']??'');$role=in_array($_POST['role']??'', ['student','counselor'],true)?$_POST['role']:'student';if($name===''||$mobile==='')$error='نام و موبایل الزامی است.';else try{db()->prepare('UPDATE users SET name=?,mobile=?,role=? WHERE id=? AND role<>\'admin\'')->execute([$name,$mobile,$role,$uid]);if(trim($_POST['new_password']??'')!==''){if(strlen($_POST['new_password'])<6)$error='رمز جدید حداقل ۶ کاراکتر باشد.';else db()->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($_POST['new_password'],PASSWORD_DEFAULT),$uid]);}if(!$error){audit('user_updated','user',$uid);flash('اطلاعات حساب به‌روزرسانی شد.');redirect('/admin/users.php?id='.$uid);}}catch(PDOException $e){$error='موبایل تکراری است یا ذخیره انجام نشد.';} }elseif($action==='toggle'){db()->prepare('UPDATE users SET is_active=1-is_active WHERE id=? AND role<>\'admin\'')->execute([$uid]);audit('user_toggled','user',$uid);flash('وضعیت حساب تغییر کرد.');redirect('/admin/users.php');}}
$users=db()->query("SELECT id,name,mobile,role,is_active,last_login_at,created_at FROM users ORDER BY FIELD(role,'admin','counselor','student'),name");$roles=['admin'=>'مدیر','counselor'=>'مشاور','student'=>'دانش‌آموز'];layout_start('مدیریت کاربران');?><div class="page-head"><div><p class="eyebrow">مدیریت دسترسی</p><h1>کاربران</h1></div><a class="button secondary" href="<?=e(url('/admin/index.php'))?>">بازگشت</a></div><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><?php if($edit && $edit['role']!=='admin'):?><div class="card"><h2>ویرایش حساب: <?=e($edit['name'])?></h2><form class="form-grid" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=$edit['id']?>"><label>نام<input name="name" value="<?=e($edit['name'])?>" required></label><label>موبایل<input name="mobile" value="<?=e($edit['mobile'])?>" required></label><label>نقش<select name="role"><option value="student" <?=$edit['role']==='student'?'selected':''?>>دانش‌آموز</option><option value="counselor" <?=$edit['role']==='counselor'?'selected':''?>>مشاور</option></select></label><label>رمز جدید، اختیاری<input type="password" name="new_password" minlength="6"></label><button class="button">ذخیره تغییرات</button></form></div><?php endif;?><div class="card table-wrap"><table><thead><tr><th>نام</th><th>موبایل</th><th>نقش</th><th>وضعیت</th><th>آخرین ورود</th><th>عملیات</th></tr></thead><tbody><?php while($u=$users->fetch()):?><tr><td><?=e($u['name'])?></td><td><?=e($u['mobile'])?></td><td><?=e($roles[$u['role']]??$u['role'])?></td><td><?= $u['is_active']?'فعال':'غیرفعال'?></td><td><?=e($u['last_login_at']??'—')?></td><td><?php if($u['role']!=='admin'):?><a href="<?=e(url('/admin/users.php?id='.$u['id']))?>">ویرایش</a><form class="inline" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$u['id']?>"><button><?= $u['is_active']?'غیرفعال‌سازی':'فعال‌سازی'?></button></form><?php else:?>حساب اصلی مدیر<?php endif;?></td></tr><?php endwhile;?></tbody></table></div><?php layout_end(); ?>
